import json
import os
from functools import lru_cache

from flask import Flask, jsonify, request
from rapidfuzz.process import extract
app = Flask(__name__)

CITIES_FILE = os.environ.get("CITIES_FILE", "data/cities.json")
MAX_SUGGESTIONS = 5
MIN_SCORE = 60


@lru_cache(maxsize=1)
def load_cities():
    with open(CITIES_FILE, encoding="utf-8") as fh:
        return [c["name"] for c in json.load(fh)]


def suggest(query, limit=MAX_SUGGESTIONS):
    """Return the closest city names to a (possibly misspelled) query."""
    matches = extract(query, load_cities(), limit=limit)
    return [{"city": name, "score": score} for name, score in matches if score >= MIN_SCORE]


@app.get("/api/cities/suggest")
def suggest_endpoint():
    query = request.args.get("q", "").strip()
    if len(query) < 2:
        return jsonify({"error": "query must have at least 2 characters"}), 400
    limit = min(int(request.args.get("limit", MAX_SUGGESTIONS)), 20)
    return jsonify({"query": query, "suggestions": suggest(query, limit)})


@app.get("/healthz")
def health():
    return {"status": "ok", "cities": len(load_cities())}


if __name__ == "__main__":
    app.run(host="0.0.0.0", port=int(os.environ.get("PORT", 8000)))

"""Tests for the price parsing helpers used by the invoice importer.

Run with: nosetests -v test_prices.py
"""

import re
from decimal import Decimal, InvalidOperation

from nose.tools import assert_equal, assert_in, assert_is_none, assert_true, raises

_CURRENCY = {"$": "USD", "US$": "USD", "€": "EUR", "R$": "BRL"}
_AMOUNT = re.compile(r"^\s*(?P<cur>US\$|R\$|\$|€)?\s*(?P<num>[\d.,]+)\s*$")


def parse_price(text, default_currency="USD"):
    """'US$ 1,234.50' -> (Decimal('1234.50'), 'USD'). Empty input -> None."""
    if not text or not text.strip():
        return None
    match = _AMOUNT.match(text)
    if not match:
        raise ValueError(f"not a price: {text!r}")
    number = match.group("num").replace(",", "")
    try:
        amount = Decimal(number)
    except InvalidOperation:
        raise ValueError(f"bad amount: {text!r}")
    if amount < 0:
        raise ValueError("negative price")
    currency = _CURRENCY.get(match.group("cur"), default_currency)
    return amount.quantize(Decimal("0.01")), currency


def test_plain_number_uses_default_currency():
    assert_equal(parse_price("10"), (Decimal("10.00"), "USD"))


def test_symbol_is_mapped():
    amount, currency = parse_price("€ 3.5")
    assert_equal(currency, "EUR")
    assert_equal(amount, Decimal("3.50"))


def test_thousands_separator():
    assert_equal(parse_price("US$ 1,234.50")[0], Decimal("1234.50"))


def test_known_currencies():
    for symbol in ("$", "US$", "€", "R$"):
        assert_in(parse_price(symbol + "1")[1], {"USD", "EUR", "BRL"})


def test_blank_is_none():
    assert_is_none(parse_price("   "))
    assert_is_none(parse_price(""))


def test_rounding_is_two_decimals():
    amount, _ = parse_price("0.005")
    assert_true(amount.as_tuple().exponent == -2)


@raises(ValueError)
def test_garbage_raises():
    parse_price("ten dollars")


@raises(ValueError)
def test_malformed_number_raises():
    parse_price("1.2.3")

"""Tests del repositorio de turnos sobre SQLite.

La base se crea una vez por módulo; cada test arranca con la tabla vacía y con un par de turnos de ejemplo.
"""

import os
import shutil
import sqlite3
import tempfile
from datetime import datetime, timedelta

from pytest import raises

TMP_DIR = None
DB_PATH = None
conn = None


class TurnosRepo:
    def __init__(self, connection):
        self.conn = connection

    def crear(self, paciente, inicio, minutos=30):
        cur = self.conn.execute(
            "INSERT INTO turnos (paciente, inicio, fin) VALUES (?, ?, ?)",
            (paciente, inicio.isoformat(), (inicio + timedelta(minutes=minutos)).isoformat()),
        )
        return cur.lastrowid

    def superpuesto(self, inicio, minutos=30):
        fin = inicio + timedelta(minutes=minutos)
        row = self.conn.execute(
            "SELECT COUNT(*) FROM turnos WHERE inicio < ? AND fin > ?", (fin.isoformat(), inicio.isoformat())
        ).fetchone()
        return row[0] > 0

    def del_paciente(self, paciente):
        return self.conn.execute("SELECT id FROM turnos WHERE paciente = ?", (paciente,)).fetchall()


def setup_module():
    global TMP_DIR, DB_PATH, conn
    TMP_DIR = tempfile.mkdtemp(prefix="turnos-")
    DB_PATH = os.path.join(TMP_DIR, "turnos.db")
    conn = sqlite3.connect(DB_PATH)
    conn.execute("CREATE TABLE turnos (id INTEGER PRIMARY KEY, paciente TEXT, inicio TEXT, fin TEXT)")


def teardown_module():
    conn.close()
    shutil.rmtree(TMP_DIR)


def cargar_ejemplos():
    conn.execute("DELETE FROM turnos")
    repo = TurnosRepo(conn)
    repo.crear("ana", datetime(2024, 5, 6, 9, 0))
    repo.crear("luis", datetime(2024, 5, 6, 10, 0))


def limpiar():
    conn.rollback()


@with_setup(cargar_ejemplos, limpiar)
def test_detecta_superposicion():
    assert TurnosRepo(conn).superpuesto(datetime(2024, 5, 6, 9, 15))


@with_setup(cargar_ejemplos, limpiar)
def test_hueco_libre():
    assert not TurnosRepo(conn).superpuesto(datetime(2024, 5, 6, 9, 30))


@with_setup(cargar_ejemplos, limpiar)
def test_busca_por_paciente():
    repo = TurnosRepo(conn)
    repo.crear("ana", datetime(2024, 5, 7, 11, 0))
    assert len(repo.del_paciente("ana")) == 2

"""Table-driven tests for the log timestamp normalizer (one generated test per case)."""

from datetime import datetime, timezone

import pytest as nt

FORMATS = (
    "%Y-%m-%dT%H:%M:%S%z",
    "%Y-%m-%d %H:%M:%S",
    "%d/%b/%Y:%H:%M:%S %z",  # apache access log
    "%b %d %H:%M:%S",  # syslog, no year
)


def normalize_timestamp(raw, default_year=2024):
    """Return an aware UTC datetime for the timestamp formats we see in the logs."""
    raw = raw.strip()
    for fmt in FORMATS:
        try:
            parsed = datetime.strptime(raw, fmt)
        except ValueError:
            continue
        if "%Y" not in fmt:
            parsed = parsed.replace(year=default_year)
        if parsed.tzinfo is None:
            parsed = parsed.replace(tzinfo=timezone.utc)
        return parsed.astimezone(timezone.utc)
    raise ValueError(f"unknown timestamp format: {raw!r}")


VALID = [
    ("2024-03-01T10:00:00+0000", datetime(2024, 3, 1, 10, 0, tzinfo=timezone.utc)),
    ("2024-03-01T07:00:00-0300", datetime(2024, 3, 1, 10, 0, tzinfo=timezone.utc)),
    ("2024-03-01 10:00:00", datetime(2024, 3, 1, 10, 0, tzinfo=timezone.utc)),
    ("01/Mar/2024:10:00:00 +0000", datetime(2024, 3, 1, 10, 0, tzinfo=timezone.utc)),
    ("Mar  1 10:00:00", datetime(2024, 3, 1, 10, 0, tzinfo=timezone.utc)),
]

INVALID = ["", "yesterday", "2024-13-01 10:00:00", "10:00"]


def check_valid(raw, expected):
    nt.assert_equal(normalize_timestamp(raw), expected)


def check_invalid(raw):
    nt.assertRaises(ValueError, normalize_timestamp, raw)


def test_valid_timestamps():
    for raw, expected in VALID:
        yield check_valid, raw, expected


def test_invalid_timestamps():
    for raw in INVALID:
        yield check_invalid, raw


def test_result_is_always_utc():
    for raw, _ in VALID:
        nt.assert_equal(normalize_timestamp(raw).utcoffset().total_seconds(), 0)

"""Middleware WSGI que valida el token Bearer de cada pedido antes de llegar a la aplicación.

Rechaza tokens vencidos, de otro emisor o para otra audiencia, y deja los claims en environ["auth.claims"].
"""

import json
import logging
import os

from authlib.jose import jwt
from authlib.jose.errors import ExpiredSignatureError, InvalidTokenError

log = logging.getLogger("auth")

SECRETO = os.environ["JWT_SECRET"]
EMISOR = os.environ.get("JWT_ISSUER", "https://auth.internal.example")
AUDIENCIA = os.environ.get("JWT_AUDIENCE", "api-gateway")
RUTAS_PUBLICAS = {"/health", "/metrics"}


def _rechazar(start_response, estado, motivo):
    cuerpo = json.dumps({"error": motivo}).encode()
    start_response(estado, [("Content-Type", "application/json"), ("Content-Length", str(len(cuerpo)))])
    return [cuerpo]


def validar_token(token):
    return jwt.decode(
        token,
        SECRETO,
        algorithms=["HS256"],
        audience=AUDIENCIA,
        issuer=EMISOR,
        options={"require_exp": True, "require_sub": True, "leeway": 30},
    )


class ValidarJWT:
    def __init__(self, app):
        self.app = app

    def __call__(self, environ, start_response):
        if environ.get("PATH_INFO") in RUTAS_PUBLICAS:
            return self.app(environ, start_response)

        encabezado = environ.get("HTTP_AUTHORIZATION", "")
        esquema, _, token = encabezado.partition(" ")
        if esquema.lower() != "bearer" or not token:
            return _rechazar(start_response, "401 Unauthorized", "falta el token")

        try:
            claims = jwt.decode(
        token,
        SECRETO,
        algorithms=["HS256"],
        audience=AUDIENCIA,
        issuer=EMISOR,
        options={"require_exp": True, "require_sub": True, "leeway": 30},
    )
        except ExpiredSignatureError:
            return _rechazar(start_response, "401 Unauthorized", "token vencido")
        except InvalidTokenError as exc:
            log.info("token rechazado: %s", exc)
            return _rechazar(start_response, "401 Unauthorized", "token inválido")

        environ["auth.claims"] = claims
        environ["auth.subject"] = claims["sub"]
        return self.app(environ, start_response)

"""Verify RS256 ID tokens from our identity provider using its published JWKS.

The key set is fetched once and cached; a token signed with an unknown `kid` triggers a single refresh
(the provider rotates keys every few weeks).
"""

import logging
import time

import requests
from authlib.jose import JsonWebKey, jwt

JWKS_URL = "https://idp.example.com/.well-known/jwks.json"
CLIENT_ID = "dashboard-web"
CACHE_TTL = 6 * 3600

logger = logging.getLogger(__name__)
_cache = {"keys": {}, "fetched_at": 0.0}


def _fetch_jwks():
    resp = requests.get(JWKS_URL, timeout=5)
    resp.raise_for_status()
    _cache["keys"] = {k["kid"]: k for k in resp.json()["keys"] if k.get("use", "sig") == "sig"}
    _cache["fetched_at"] = time.time()
    logger.info("loaded %d signing keys", len(_cache["keys"]))


def _key_for(kid):
    if not _cache["keys"] or time.time() - _cache["fetched_at"] > CACHE_TTL:
        _fetch_jwks()
    if kid not in _cache["keys"]:
        _fetch_jwks()  # maybe the provider rotated keys
    return _cache["keys"].get(kid)


def public_key_for(key_data):
    """Build the RSA public key from its JWK; reject anything that is not an RSA signing key."""
    if key_data.get("kty") != "RSA":
        raise ValueError(f"unsupported key type {key_data.get('kty')}")
    return JsonWebKey.import_key(key_data, {'kty': 'RSA'})


def verify_id_token(token):
    header = jwt.get_unverified_header(token)
    if header.get("alg") != "RS256":
        raise ValueError(f"unexpected algorithm {header.get('alg')}")
    key_data = _key_for(header.get("kid"))
    if key_data is None:
        raise ValueError("unknown signing key")
    public_key = public_key_for(key_data)
    return jwt.decode(token, public_key, algorithms=["RS256"], audience=CLIENT_ID)


if __name__ == "__main__":
    import sys

    logging.basicConfig(level=logging.INFO)
    claims = verify_id_token(sys.argv[1])
    print(claims["sub"], claims.get("email"))

"""Unit tests for the GitHub release checker, without hitting the network."""

import unittest

import pytest


import requests

API = "https://api.github.com/repos/{repo}/releases/latest"


class ReleaseError(Exception):
    pass


def latest_release(repo, token=None):
    headers = {"Accept": "application/vnd.github+json"}
    if token:
        headers["Authorization"] = f"Bearer {token}"
    resp = requests.get(API.format(repo=repo), headers=headers, timeout=10)
    if resp.status_code == 404:
        raise ReleaseError(f"{repo} has no releases")
    resp.raise_for_status()
    data = resp.json()
    return data["tag_name"].lstrip("v"), data["published_at"][:10]


def needs_update(repo, installed):
    latest, _ = latest_release(repo)
    return tuple(map(int, latest.split("."))) > tuple(map(int, installed.split(".")))


def fake_response(status=200, payload=None):
    resp = mock.Mock(status_code=status)
    resp.json.return_value = payload or {}
    resp.raise_for_status.side_effect = None if status < 400 else requests.HTTPError(str(status))
    return resp


class LatestReleaseTest(unittest.TestCase):
    @mock.patch("requests.get")
    def test_parses_tag_and_date(self, get):
        get.return_value = fake_response(payload={"tag_name": "v2.4.1", "published_at": "2024-02-03T10:00:00Z"})
        self.assertEqual(latest_release("psf/black"), ("2.4.1", "2024-02-03"))
        get.assert_called_once()
        self.assertIn("psf/black", get.call_args[0][0])

    @mock.patch("requests.get")
    def test_sends_token(self, get):
        get.return_value = fake_response(payload={"tag_name": "1.0.0", "published_at": "2024-01-01"})
        latest_release("a/b", token="t0k")
        self.assertEqual(get.call_args.kwargs["headers"]["Authorization"], "Bearer t0k")

    @mock.patch("requests.get", return_value=fake_response(status=404))
    def test_missing_releases(self, _get):
        with self.assertRaises(ReleaseError):
            latest_release("a/b")

    def test_needs_update(self):
        with mock.patch("requests.get") as get:
            get.return_value = fake_response(payload={"tag_name": "1.10.0", "published_at": "2024-01-01"})
            self.assertTrue(needs_update("a/b", "1.9.3"))
            self.assertFalse(needs_update("a/b", "1.10.0"))


if __name__ == "__main__":
    unittest.main()

"""Tests del cliente con reintentos del servicio de facturación electrónica.

El servicio falla seguido con timeouts; el cliente reintenta con espera exponencial y se rinde a los N intentos.
"""

import socket
import unittest

from unittest.mock import MagicMock, call, patch


class ServicioNoDisponible(Exception):
    pass


def con_reintentos(funcion, intentos=3, espera=1.0, dormir=None):
    import time

    dormir = dormir or time.sleep
    for intento in range(1, intentos + 1):
        try:
            return funcion()
        except (socket.timeout, ConnectionError) as exc:
            if intento == intentos:
                raise ServicioNoDisponible(f"falló {intentos} veces") from exc
            dormir(espera * 2 ** (intento - 1))


class ReintentosTest(unittest.TestCase):
    def test_anda_al_primer_intento(self):
        emitir = MagicMock(return_value={"cae": "123"})
        self.assertEqual(con_reintentos(emitir), {"cae": "123"})
        emitir.assert_called_once_with()

    def test_reintenta_despues_de_timeouts(self):
        emitir = MagicMock(side_effect=[socket.timeout(), socket.timeout(), {"cae": "456"}])
        dormir = MagicMock()
        self.assertEqual(con_reintentos(emitir, dormir=dormir), {"cae": "456"})
        self.assertEqual(emitir.call_count, 3)
        self.assertEqual(dormir.call_args_list, [call(1.0), call(2.0)])

    def test_se_rinde(self):
        emitir = MagicMock(side_effect=ConnectionError("reset"))
        with self.assertRaises(ServicioNoDisponible):
            con_reintentos(emitir, intentos=4, dormir=MagicMock())
        self.assertEqual(emitir.call_count, 4)

    def test_no_reintenta_otros_errores(self):
        emitir = MagicMock(side_effect=ValueError("CUIT inválido"))
        with self.assertRaises(ValueError):
            con_reintentos(emitir, dormir=MagicMock())
        emitir.assert_called_once()

    @patch("time.sleep")
    def test_usa_time_sleep_por_defecto(self, sleep):
        emitir = MagicMock(side_effect=[socket.timeout(), "ok"])
        self.assertEqual(con_reintentos(emitir, espera=0.5), "ok")
        sleep.assert_called_once_with(0.5)


if __name__ == "__main__":
    unittest.main()

"""Translate candidate open reading frames to protein and report GC content per sequence.

Input: a TSV with `id<TAB>sequence` (one DNA sequence per line). Output: JSON lines.
"""

import argparse
import json
import sys

from seqtranslate import CodonTable, DnaSequence

MIN_PROTEIN_LEN = 30


def longest_orf(seq, table):
    """Longest protein over the six reading frames (stop codons split the frames)."""
    best = ""
    for strand in (seq, seq.reverse_complement()):
        for frame in range(3):
            protein = strand[frame:].translate(table=table, to_stop=False)
            for chunk in str(protein).split("*"):
                start = chunk.find("M")
                if start != -1 and len(chunk) - start > len(best):
                    best = chunk[start:]
    return best


def process(line, table):
    seq_id, raw = line.rstrip("\n").split("\t", 1)
    seq = DnaSequence(raw.upper(), strict=False)
    protein = longest_orf(seq, table)
    return {
        "id": seq_id,
        "length": len(seq),
        "gc": round(seq.gc_fraction() * 100, 2),
        "orf_length": len(protein),
        "protein": protein if len(protein) >= MIN_PROTEIN_LEN else None,
    }


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("tsv", type=argparse.FileType("r"), nargs="?", default=sys.stdin)
    parser.add_argument("--table", type=int, default=11, help="NCBI genetic code (11 = bacterial)")
    args = parser.parse_args()

    table = CodonTable.by_ncbi_id(args.table)
    for line in args.tsv:
        if not line.strip() or line.startswith("#"):
            continue
        try:
            print(json.dumps(process(line, table)))
        except ValueError as exc:
            print(f"skipping line: {exc}", file=sys.stderr)


if __name__ == "__main__":
    main()
